package com.husainking.project3;
import android.app.*; import android.app.admin.DevicePolicyManager; import android.content.*; import android.os.*; import android.widget.*;
public class MainActivity extends Activity { DevicePolicyManager dpm; ComponentName admin; public void onCreate(Bundle b){super.onCreate(b); dpm=(DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE); admin=new ComponentName(this,AdminReceiver.class); LinearLayout l=new LinearLayout(this); l.setOrientation(LinearLayout.VERTICAL); l.setPadding(32,48,32,32); TextView t=new TextView(this); t.setText("H.K Phone Manager\\n\\nAuthorized device-management foundation"); t.setTextSize(22); l.addView(t); Button enroll=new Button(this); enroll.setText("Enable Device Management"); enroll.setOnClickListener(v->{startActivity(new Intent(DevicePolicyManager.ACTION_ADD_DEVICE_ADMIN).putExtra(DevicePolicyManager.EXTRA_DEVICE_ADMIN,admin).putExtra(DevicePolicyManager.EXTRA_ADD_EXPLANATION,"Enable this only on your own device for authorized remote management."));}); l.addView(enroll); Button lock=new Button(this); lock.setText("Lock This Device"); lock.setOnClickListener(v->{if(dpm.isAdminActive(admin)) dpm.lockNow(); else Toast.makeText(this,"Enable Device Management first",Toast.LENGTH_SHORT).show();}); l.addView(lock); setContentView(l); }}
